BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L2 — Shares issued in business combination weighted from acquisition date
(2, 'Earnings Per Share', 'Glenfield Industries had 500,000 common shares outstanding on January 1, 2026. On September 1, 2026, Glenfield issued 120,000 shares to acquire Branford Corp. in a business combination. What is Glenfield''s weighted-average number of common shares outstanding for 2026?', '["540,000", "620,000", "560,000", "500,000"]'::jsonb, 0, 'Under ASC 260-10-45-10, shares issued in a business combination are included in the weighted-average from the acquisition date. Glenfield includes 500,000 for the full year plus 120,000 × 4/12 = 40,000, totaling 540,000 shares. Choice B (620,000) incorrectly includes the acquired shares for the entire year rather than weighting them from the September 1 acquisition date.', 'medium', 2),

-- Q2: medium / L2 — Diluted EPS with convertible preferred using if-converted method
(2, 'Earnings Per Share', 'Haverbrook Corp. reports net income of $750,000 with 200,000 weighted-average common shares outstanding. Haverbrook has 10,000 shares of $50 par, 8% convertible preferred stock, each convertible into 3 common shares. Basic EPS is $3.55. What is diluted EPS?', '["$3.55", "$3.26", "$3.09", "$3.75"]'::jsonb, 1, 'Under ASC 260-10-45-40, diluted EPS for convertible preferred stock uses the if-converted method: preferred dividends ($40,000) are added back to the numerator and converted shares (10,000 × 3 = 30,000) are added to the denominator, yielding $750,000 / 230,000 = $3.26. Since $3.26 < $3.55, the conversion is dilutive. However, Choice C ($3.09) deducts preferred dividends in both the basic and diluted calculations, double-counting the deduction.', 'medium', 2),

-- Q3: easy / L1 — Simple vs. complex capital structure definition
(2, 'Earnings Per Share', 'Under ASC 260, which of the following best describes a simple capital structure?', '["A capital structure with only common stock and convertible preferred stock outstanding", "A capital structure with common stock and stock options but no convertible debt", "A capital structure with no potentially dilutive securities outstanding", "A capital structure with fewer than three classes of equity securities"]'::jsonb, 2, 'Under ASC 260-10-15-2, a simple capital structure exists when an entity has no outstanding potentially dilutive securities such as convertible bonds, convertible preferred stock, options, or warrants. Entities with a simple structure present only basic EPS. Choice A is incorrect because convertible preferred stock is a potentially dilutive security, making the structure complex.', 'easy', 1),

-- Q4: hard / L4 — Loss from continuing operations makes all dilutive securities antidilutive
(2, 'Earnings Per Share', 'Meridian Holdings reports a loss from continuing operations of $200,000 and income from discontinued operations of $350,000, resulting in net income of $150,000. The company has 100,000 weighted-average shares and 5,000 in-the-money stock options (exercise price $25, average market price $50). A junior analyst proposes including the options in diluted EPS because net income is positive. Evaluate this approach.', '["The approach is correct because net income determines whether securities are dilutive", "The approach is correct because the options are in the money and should always be included", "The approach is incorrect because options cannot be dilutive when a discontinued operation is present", "The approach is incorrect because income from continuing operations is the control number, and the loss makes all potentially dilutive securities antidilutive"]'::jsonb, 3, 'Under ASC 260-10-45-19, income from continuing operations is the control number for determining whether potentially dilutive securities are included in diluted EPS. Because Meridian reports a loss from continuing operations, including the options would reduce the per-share loss (an antidilutive effect), so they must be excluded. Choice A is incorrect because ASC 260 uses income from continuing operations, not net income, as the dilution test basis.', 'hard', 4),

-- Q5: medium / L2 — RSUs and treasury stock method with unrecognized compensation cost
(2, 'Earnings Per Share', 'Pryor Technologies has 150,000 weighted-average common shares and net income of $600,000. The company granted 12,000 restricted stock units (RSUs) that vest over 3 years. At December 31, 2026, the average unrecognized compensation cost per RSU is $18, and the average market price during 2026 was $45 per share. Using the treasury stock method, how many incremental shares from the RSUs are included in diluted EPS?', '["12,000 shares", "4,800 shares", "0 shares", "7,200 shares"]'::jsonb, 3, 'Under ASC 260-10-45-28, RSUs are included in diluted EPS using the treasury stock method. The assumed proceeds equal the unrecognized compensation cost: 12,000 × $18 = $216,000. Shares assumed repurchased = $216,000 / $45 average market price = 4,800. Incremental shares = 12,000 − 4,800 = 7,200. However, Choice A (12,000) treats all RSUs as incremental without accounting for the assumed treasury stock repurchase.', 'medium', 2),

-- Q6: medium / L2 — Actual mid-year conversion: numerator adjustment for pre-conversion interest
(2, 'Earnings Per Share', 'Oakmont Corp. had 200,000 common shares outstanding on January 1, 2026. On July 1, 2026, holders of $500,000 face value, 6% convertible bonds exercised their conversion right, receiving 25,000 common shares. The tax rate is 25%. What is the numerator adjustment for these bonds in computing diluted EPS?', '["$15,000", "$22,500", "$11,250", "$30,000"]'::jsonb, 2, 'Under ASC 260-10-45-40, diluted EPS assumes conversion at the beginning of the period. Since the bonds were actually converted on July 1, only the pre-conversion interest (January–June) is added back on an after-tax basis: $500,000 × 6% × 6/12 × (1 − 0.25) = $11,250. However, Choice A ($15,000) fails to apply the tax effect to the interest savings, overstating the numerator adjustment.', 'medium', 2),

-- Q7: hard / L3 — Stock dividend after year-end but before statements issued requires retroactive restatement
(2, 'Earnings Per Share', 'Fairview Corp. reported basic EPS of $4.50 for the year ended December 31, 2025, based on 200,000 weighted-average shares and net income of $900,000. On February 15, 2026, before the 2025 financial statements were issued, Fairview declared a 20% stock dividend. How does this subsequent event affect the reported EPS for 2025?', '["EPS must be retroactively restated to $3.75 using 240,000 adjusted shares", "EPS remains $4.50 with the stock dividend disclosed in the notes only", "EPS is restated to $3.60 using 250,000 adjusted shares", "EPS is restated to $4.09 using 220,000 adjusted shares"]'::jsonb, 0, 'Under ASC 260-10-55-12, stock dividends occurring after the balance sheet date but before financial statements are issued require retroactive adjustment of all per-share amounts. The weighted-average shares are adjusted to 200,000 × 1.20 = 240,000, and EPS is restated to $900,000 / 240,000 = $3.75. Choice B is incorrect because ASC 260 requires retroactive restatement, not merely note disclosure, for post-period stock dividends.', 'hard', 3),

-- Q8: medium / L3 — Two-class method for participating securities
(2, 'Earnings Per Share', 'Crestwood Inc. reports net income of $1,000,000 with 400,000 common shares and 100,000 participating preferred shares outstanding. The preferred shares participate equally in undistributed earnings. Total dividends declared are $200,000. Analyze how the two-class method affects basic EPS compared to a simple deduction of preferred dividends.', '["Basic EPS is $2.40 under both methods because preferred dividends are the same", "Basic EPS is $2.00 under the two-class method because undistributed earnings are shared proportionally between common and participating preferred", "Basic EPS is $1.60 under the two-class method because all dividends reduce the common numerator twice", "Basic EPS is $2.50 under the two-class method because participating preferred shares are excluded from the denominator"]'::jsonb, 1, 'Under ASC 260-10-45-60, participating securities require the two-class method for basic EPS. Both declared dividends and undistributed earnings ($800,000) are allocated proportionally. Common shareholders receive 80% (400,000/500,000) of undistributed earnings ($640,000) plus their share of dividends ($160,000) = $800,000, yielding EPS of $2.00. However, Choice A ($2.40) ignores the participating feature''s claim on undistributed earnings.', 'medium', 3),

-- Q9: medium / L2 — Warrants and treasury stock method calculation
(2, 'Earnings Per Share', 'Belmont Industries has 300,000 weighted-average common shares outstanding and net income of $1,200,000. Belmont has 20,000 warrants outstanding with an exercise price of $30 per warrant. The average market price during 2026 was $50 per share. What is diluted EPS?', '["$3.75", "$4.00", "$3.85", "$3.90"]'::jsonb, 3, 'Under ASC 260-10-45-22, warrants are treated identically to stock options using the treasury stock method. Proceeds = 20,000 × $30 = $600,000; shares repurchased = $600,000 / $50 = 12,000; incremental shares = 20,000 − 12,000 = 8,000. Diluted EPS = $1,200,000 / 308,000 = $3.90. However, Choice A ($3.75) adds all 20,000 warrant shares without reducing for assumed treasury stock repurchases.', 'medium', 2),

-- Q10: medium / L2 — Treasury stock repurchase mid-year reduces weighted-average shares
(2, 'Earnings Per Share', 'Sterling Enterprises had 400,000 common shares outstanding on January 1, 2026. On October 1, 2026, Sterling repurchased 48,000 shares as treasury stock. Net income for 2026 was $970,000 with no preferred stock. What is basic EPS?', '["$2.76", "$2.43", "$2.17", "$2.50"]'::jsonb, 3, 'Under ASC 260-10-45-10, treasury stock repurchases reduce the weighted-average share count from the repurchase date. Sterling''s weighted-average = (400,000 × 9/12) + (352,000 × 3/12) = 300,000 + 88,000 = 388,000 shares. Basic EPS = $970,000 / 388,000 = $2.50. Choice A ($2.76) incorrectly uses the year-end share count of 352,000 rather than the weighted-average.', 'medium', 2),

-- Q11: hard / L4 — Ranking three convertible securities by incremental EPS (most to least dilutive)
(2, 'Earnings Per Share', 'Pinnacle Corp. has net income of $2,000,000 and 500,000 weighted-average common shares. Three convertible securities are outstanding: (1) 8% bonds ($1,000,000 face, converting to 50,000 shares, tax rate 25%), (2) 5% bonds ($800,000 face, converting to 60,000 shares, tax rate 25%), and (3) 10% preferred stock ($500,000 par, converting to 30,000 shares). Evaluate the correct ranking from most dilutive to least dilutive.', '["Security 1, Security 2, Security 3", "Security 3, Security 1, Security 2", "Security 2, Security 1, Security 3", "Security 2, Security 3, Security 1"]'::jsonb, 2, 'Under ASC 260-10-45-44, potentially dilutive securities are ranked by per-share impact (incremental EPS) from lowest to highest. Security 2: $30,000 / 60,000 = $0.50; Security 1: $60,000 / 50,000 = $1.20; Security 3: $50,000 / 30,000 = $1.67. The correct order is 2, 1, 3. However, Choice B reverses this ranking by testing the least dilutive security first, which would incorrectly determine the dilution cutoff point.', 'hard', 4),

-- Q12: medium / L2 — EPS presentation with discontinued operations
(2, 'Earnings Per Share', 'Redwood Corp. reports income from continuing operations of $480,000 and a loss from discontinued operations (net of tax) of $80,000, resulting in net income of $400,000. Redwood has 100,000 weighted-average common shares and no preferred stock. What amounts must Redwood report for per-share data on the income statement?', '["Only net income per share of $4.00 is required on the face of the income statement", "Only income from continuing operations per share of $4.80 is required on the face", "Both continuing operations EPS and discontinued operations EPS on the face, but not net income EPS", "Both continuing operations EPS and net income EPS on the face, with discontinued operations EPS on the face or in notes"]'::jsonb, 3, 'Under ASC 260-10-45-2, entities with discontinued operations must present EPS for both income from continuing operations ($4.80) and net income ($4.00) on the face of the income statement. Per-share data for discontinued operations may be presented on the face or disclosed in the notes. Choice A is incorrect because presenting only net income EPS omits the required continuing operations per-share figure.', 'medium', 2),

-- Q13: easy / L1 — Control number definition for dilutive testing
(2, 'Earnings Per Share', 'Under ASC 260, what is the control number used to determine whether potentially dilutive securities are included in diluted EPS?', '["Income from continuing operations attributable to common shareholders", "Net income attributable to common shareholders", "Comprehensive income attributable to common shareholders", "Operating income attributable to common shareholders"]'::jsonb, 0, 'Under ASC 260-10-45-19, income from continuing operations (adjusted for preferred dividends) serves as the control number for testing whether potentially dilutive securities are dilutive or antidilutive. If continuing operations shows a loss, all potential common shares are antidilutive. Choice B is incorrect because net income includes discontinued operations, which could mask a continuing-operations loss.', 'easy', 1),

-- Q14: medium / L3 — Effect of share repurchase on basic EPS analysis (same earnings, fewer shares)
(2, 'Earnings Per Share', 'Westbrook Industries earned net income of $2,000,000 in both 2025 and 2026. Westbrook had 500,000 shares outstanding for all of 2025. On January 1, 2026, Westbrook used $2,500,000 in cash to repurchase 50,000 shares. Analyze the effect of this repurchase on basic EPS.', '["Basic EPS decreases because the cash used for the repurchase reduces net income", "Basic EPS increases from $4.00 to $4.44 because the same earnings are divided by fewer shares", "Basic EPS remains at $4.00 because the repurchase does not affect the EPS calculation", "Basic EPS decreases from $4.00 to $3.64 because the repurchase adds shares to the denominator"]'::jsonb, 1, 'Under ASC 260-10-45-10, share repurchases reduce the weighted-average common shares outstanding, thereby increasing basic EPS when earnings remain constant. With 450,000 shares, EPS rises from $4.00 to $4.44. However, Choice A assumes the cash outflow reduces net income, whereas the repurchase is a treasury stock transaction affecting equity, not the income statement.', 'medium', 3),

-- Q15: medium / L3 — Reverse stock split requires retroactive EPS restatement
(2, 'Earnings Per Share', 'Clarkson Technologies reported basic EPS of $1.20 for the year ended December 31, 2025, based on 600,000 weighted-average shares and net income of $720,000. On March 1, 2026, Clarkson executed a 1-for-3 reverse stock split before issuing the 2025 financial statements. What is the effect on the 2025 reported EPS?', '["EPS remains $1.20 with the reverse split disclosed in the notes", "EPS is restated to $0.40, reflecting the tripled share count", "EPS is restated to $3.60, reflecting the reduced share count of 200,000", "EPS is restated to $2.40, reflecting a reduction to 300,000 shares"]'::jsonb, 2, 'Under ASC 260-10-55-12, reverse stock splits occurring after the balance sheet date but before financial statements are issued require retroactive adjustment. The 1-for-3 reverse split reduces weighted-average shares from 600,000 to 200,000, restating EPS to $720,000 / 200,000 = $3.60. Choice A is incorrect because ASC 260 mandates retroactive restatement of all per-share data, not merely note disclosure.', 'medium', 3),

-- Q16: easy / L1 — Purpose of weighted-average shares in the EPS denominator
(2, 'Earnings Per Share', 'What is the purpose of using weighted-average common shares outstanding in the EPS denominator?', '["To reflect only the shares outstanding at the end of the reporting period", "To include all authorized but unissued shares in the calculation", "To exclude shares held as treasury stock from the total outstanding", "To reflect the time-weighted impact of share issuances and repurchases during the period"]'::jsonb, 3, 'Under ASC 260-10-45-10, the weighted-average method accounts for the timing of share issuances and repurchases, giving proportional weight based on the fraction of the period each block of shares was outstanding. Choice A is incorrect because using only end-of-period shares would ignore the timing of mid-period changes, distorting the per-share measurement.', 'easy', 1),

-- Q17: easy / L1 — EPS presentation required only for public entities
(2, 'Earnings Per Share', 'Under U.S. GAAP, which entities are required to present earnings per share on the face of the income statement?', '["All entities, whether publicly held or privately held", "Only entities with publicly traded common stock or potential common stock", "All entities with net income exceeding $1 million", "Only entities with a complex capital structure"]'::jsonb, 1, 'Under ASC 260-10-15-2, EPS presentation is required for entities with publicly traded common stock or potential common stock, including those filing or in the process of filing with the SEC. Private companies are not required to present EPS. Choice A is incorrect because ASC 260 exempts nonpublic entities from the EPS presentation requirements.', 'easy', 1),

-- Q18: easy / L1 — Definition of antidilutive security
(2, 'Earnings Per Share', 'Under ASC 260, what defines an antidilutive security?', '["A security that decreases the number of shares used in the EPS denominator", "A security that increases the EPS numerator without affecting the denominator", "A security that has been retired during the reporting period", "A security whose inclusion would increase EPS or decrease loss per share"]'::jsonb, 3, 'Under ASC 260-10-20, an antidilutive security is one whose assumed conversion or exercise would increase EPS (or decrease loss per share) rather than reduce it. Antidilutive securities are excluded from diluted EPS. Choice A is incorrect because the definition relates to the net effect on the per-share amount, not merely the direction of change in the denominator.', 'easy', 1),

-- Q19: hard / L4 — Evaluate CFO position using net income instead of continuing operations as control number
(2, 'Earnings Per Share', 'Northbridge Holdings reports a loss from continuing operations of $300,000 and income from discontinued operations of $500,000. The company has 100,000 weighted-average shares and 15,000 in-the-money stock options. The CFO argues that diluted EPS should include the stock options because the company has positive net income of $200,000. Evaluate the CFO''s position under ASC 260.', '["The CFO''s position is incorrect because income from continuing operations is the control number, and the loss makes all potentially dilutive securities antidilutive", "The CFO''s position is correct because positive net income means the company should include dilutive securities", "The CFO''s position is partially correct; options should be included for discontinued operations EPS but excluded for continuing operations EPS", "The CFO''s position is incorrect because stock options are never included in diluted EPS when discontinued operations are present"]'::jsonb, 0, 'Under ASC 260-10-45-19, income from continuing operations is the sole control number for determining dilutiveness. Because Northbridge has a loss from continuing operations, including the options would reduce the per-share loss, an antidilutive result. All potentially dilutive securities are excluded from diluted EPS for every line item. Choice C is incorrect because the control number applies uniformly — securities cannot be dilutive for one line but antidilutive for another.', 'hard', 4),

-- Q20: medium / L3 — Lower exercise price produces more incremental shares (greater dilution)
(2, 'Earnings Per Share', 'Beckett Corp. has 200,000 weighted-average shares and two batches of stock options outstanding. Batch A consists of 10,000 options with a $20 exercise price, and Batch B consists of 10,000 options with a $35 exercise price. The average market price is $50. Analyze which batch produces a larger dilutive effect on diluted EPS.', '["Both batches have the same dilutive effect because they have the same number of options", "Batch B is more dilutive because the higher exercise price generates greater assumed proceeds", "Batch A is more dilutive because the lower exercise price generates fewer assumed treasury stock repurchases, resulting in more incremental shares", "Neither batch is dilutive because options are excluded from diluted EPS"]'::jsonb, 2, 'Under ASC 260-10-45-22 (treasury stock method), a lower exercise price produces fewer assumed proceeds and therefore fewer shares assumed repurchased, increasing the net incremental shares. Batch A adds 6,000 incremental shares versus 3,000 for Batch B, creating a larger dilutive effect. Choice B is incorrect because higher proceeds actually reduce dilution by increasing the shares assumed repurchased with those proceeds.', 'medium', 3),

-- Q21: easy / L1 — Treasury stock method definition/purpose
(2, 'Earnings Per Share', 'Under ASC 260, what is the treasury stock method used to calculate?', '["The dilutive effect of stock options and warrants on earnings per share", "The gain or loss on actual repurchases of treasury stock", "The cost basis of shares held in treasury", "The weighted-average shares retired during the period"]'::jsonb, 0, 'Under ASC 260-10-45-22, the treasury stock method determines the incremental shares to add to the diluted EPS denominator for options and warrants. It assumes the proceeds from hypothetical exercise are used to repurchase shares at the average market price. Choice B is incorrect because the treasury stock method in EPS is a hypothetical calculation, not a measure of actual treasury stock transactions.', 'easy', 1),

-- Q22: medium / L3 — Mandatorily redeemable preferred stock classified as liability, dividends already in net income
(2, 'Earnings Per Share', 'Ashton Holdings has 100,000 common shares outstanding and net income of $500,000. Ashton also has $1,000,000 par value of mandatorily redeemable preferred stock classified as a liability under ASC 480, paying 7% annual dividends. The CFO deducts the $70,000 preferred dividends from the EPS numerator. Analyze whether this treatment is correct.', '["The treatment is correct because all preferred dividends must be deducted from the EPS numerator", "The treatment is incorrect; the dividends are already reflected as interest expense in net income, so no additional deduction is required", "The treatment is incorrect; mandatorily redeemable preferred dividends should be added to the numerator", "The treatment is correct because mandatorily redeemable preferred stock is always treated as equity for EPS"]'::jsonb, 1, 'Under ASC 480-10-25-4, mandatorily redeemable preferred stock is classified as a liability, and its dividend payments are recognized as interest expense in the income statement. Since these costs already reduce net income, deducting them again from the EPS numerator would double-count them. Choice A is incorrect because the numerator deduction applies only to preferred stock classified as equity under ASC 260-10-45-11.', 'medium', 3),

-- Q23: hard / L4 — Written put options dilutive when exercise price exceeds market price (reverse treasury stock method)
(2, 'Earnings Per Share', 'Kendrick Corp. has 250,000 common shares outstanding, net income of $1,000,000, and has written put options on 20,000 of its own shares with an exercise price of $60. The average market price during the year is $45. The controller excludes these puts from diluted EPS, reasoning that only call options are covered by the treasury stock method. Evaluate this conclusion.', '["The controller is correct; written put options are excluded from diluted EPS under all circumstances", "The controller is incorrect; written put options are dilutive when the exercise price exceeds the average market price, adding approximately 6,667 incremental shares using the reverse treasury stock method", "The controller is incorrect; the puts add 20,000 shares to the denominator without any treasury stock adjustment", "The controller is correct; puts are antidilutive because the exercise price of $60 exceeds the market price of $45"]'::jsonb, 1, 'Under ASC 260-10-45-35, written put options are dilutive when in the money (exercise price exceeds market price). The reverse treasury stock method assumes the entity repurchases 20,000 shares at $60 ($1,200,000) and funds this by issuing $1,200,000 / $45 = 26,667 shares, yielding 6,667 net incremental dilutive shares. However, Choice D applies call-option logic, where a higher exercise price is antidilutive — the opposite is true for put options.', 'hard', 4),

-- Q24: easy / L1 — ASC 260 as the authoritative guidance for EPS
(2, 'Earnings Per Share', 'Which ASC topic provides the authoritative guidance for computing and presenting earnings per share under U.S. GAAP?', '["ASC 260", "ASC 220", "ASC 320", "ASC 480"]'::jsonb, 0, 'ASC 260, Earnings Per Share, is the sole authoritative guidance for EPS computation and presentation for publicly held entities under U.S. GAAP. It covers basic EPS, diluted EPS, the treasury stock method, and the if-converted method. However, Choice B (ASC 220) addresses comprehensive income presentation, not earnings per share.', 'easy', 1),

-- Q25: easy / L1 — Per-share data not required for OCI
(2, 'Earnings Per Share', 'Under U.S. GAAP, for which of the following is per-share data NOT required to be presented?', '["Income from continuing operations", "Net income for the period", "Other comprehensive income", "Income from discontinued operations"]'::jsonb, 2, 'Under ASC 260-10-45-2, EPS must be presented for income from continuing operations and net income on the face of the income statement. There is no requirement to present per-share amounts for other comprehensive income. Choice A is incorrect because income from continuing operations is one of the two mandatory EPS figures required on the face of the income statement.', 'easy', 1),

-- Q26: medium / L2 — Retroactive restatement of prior-period EPS for stock split in comparative statements
(2, 'Earnings Per Share', 'Harper Manufacturing reported basic EPS of $5.00 for 2025 based on 100,000 weighted-average shares and net income of $500,000. On June 1, 2026, Harper declares a 2-for-1 stock split. When presenting comparative financial statements for 2025 alongside 2026, what basic EPS should Harper report for 2025?', '["$5.00 as originally reported, with a note about the split", "$2.50 retroactively adjusted for the stock split", "$10.00 adjusted by multiplying original EPS by the split factor", "$3.33 adjusted using 150,000 shares"]'::jsonb, 1, 'Under ASC 260-10-55-12, stock splits must be applied retroactively to all prior periods presented to ensure comparability. The 2025 weighted-average shares are adjusted from 100,000 to 200,000, yielding restated basic EPS of $500,000 / 200,000 = $2.50. Choice A is incorrect because presenting the unadjusted $5.00 would destroy comparability between years.', 'medium', 2),

-- Q27: easy / L2 — Contingently issuable shares excluded when condition not met
(2, 'Earnings Per Share', 'Cedarwood Inc. has a contingent share agreement to issue 25,000 additional common shares if cumulative net income exceeds $5 million by December 31, 2026. As of December 31, 2025, cumulative net income is $3.8 million. How should these shares be treated for basic EPS in 2025?', '["Include 25,000 shares in the weighted-average denominator because issuance is probable", "Include 12,500 shares as a partial estimate of the expected issuance", "Exclude the shares from the denominator because the contingency condition has not been met", "Include 25,000 shares in the denominator only if net income is positive"]'::jsonb, 2, 'Under ASC 260-10-45-48, contingently issuable shares are included in basic EPS only if all necessary conditions have been satisfied as of the reporting date. Because Cedarwood''s cumulative income of $3.8 million has not exceeded the $5 million threshold, the contingent shares are excluded from the 2025 basic EPS denominator. Choice A is incorrect because ASC 260 requires the condition to be met, not merely probable.', 'easy', 2),

-- Q28: medium / L3 — Performance-based stock options excluded when performance condition not met at year-end
(2, 'Earnings Per Share', 'Lakewood Corp. granted 15,000 performance-based stock options to executives, vesting only if revenue exceeds $20 million. The exercise price is $30, and the average market price is $50. At December 31, 2026, revenue is $18 million but is projected to reach $22 million in 2027. Analyze whether these options are included in Lakewood''s 2026 diluted EPS.', '["The options are excluded from 2026 diluted EPS because the performance condition has not been satisfied as of December 31, 2026", "The options are included because the performance target is projected to be met in 2027", "The options are included because they are in the money regardless of the performance condition", "The options are excluded because performance-based options are always antidilutive"]'::jsonb, 0, 'Under ASC 260-10-45-48 and 45-28, share-based awards with performance conditions are included in diluted EPS only if the performance condition would be satisfied as of the reporting date. Since revenue of $18 million does not meet the $20 million threshold at December 31, 2026, the options are excluded. Choice B is incorrect because future projections are irrelevant; the test is based on actual results as of the reporting date.', 'medium', 3),

-- Q29: hard / L4 — Evaluate antidilutive convertible bonds (per-share impact exceeds basic EPS)
(2, 'Earnings Per Share', 'Ashford Group reports net income of $800,000 with 200,000 weighted-average shares (basic EPS = $4.00). The company has $2,000,000 of 10% convertible bonds, each $1,000 bond converting into 10 shares (tax rate 25%). The controller includes these bonds in diluted EPS using the if-converted method and reports diluted EPS of $4.07. Evaluate whether this diluted EPS figure is correct.', '["The diluted EPS is correct because all convertible securities must be included in the diluted calculation", "The diluted EPS should be higher because the controller understated the interest add-back", "The diluted EPS of $4.07 is incorrect; the bonds are antidilutive because their per-share impact of $7.50 exceeds basic EPS of $4.00, so diluted EPS should equal $4.00", "The diluted EPS is incorrect because the bonds should use the treasury stock method, not the if-converted method"]'::jsonb, 2, 'Under ASC 260-10-45-17, securities are antidilutive if their inclusion increases EPS. The convertible bonds'' per-share impact is $150,000 (after-tax interest) / 20,000 shares = $7.50, exceeding basic EPS of $4.00. Including them would increase EPS, making them antidilutive and requiring exclusion. Diluted EPS equals basic EPS at $4.00. Choice A is incorrect because ASC 260 explicitly prohibits including antidilutive securities in diluted EPS.', 'hard', 4),

-- Q30: medium / L3 — Conversion ratio impact on dilutive effect of convertible bonds
(2, 'Earnings Per Share', 'Harland Corp. has two series of convertible bonds with identical terms except for the conversion ratio. Series A ($500,000 face, 6% coupon, each $1,000 bond converts to 40 shares) and Series B ($500,000 face, 6% coupon, each $1,000 bond converts to 20 shares). Tax rate is 25%. Analyze which series has a greater dilutive effect on EPS.', '["Series A is more dilutive because its higher conversion ratio produces a lower per-share impact ($1.13 vs. $2.25), adding more incremental shares per dollar of numerator adjustment", "Series B is more dilutive because it converts into fewer shares, resulting in a smaller denominator increase", "Both series have the same dilutive effect because they have the same coupon rate and face value", "Series A is more dilutive solely because it converts into more total shares regardless of the numerator adjustment"]'::jsonb, 0, 'Under ASC 260-10-45-44, dilutive impact is measured by per-share impact (numerator adjustment divided by incremental shares). Series A''s per-share impact of $1.13 is lower than Series B''s $2.25, meaning Series A dilutes EPS more because each incremental share carries less earnings support. Choice C is incorrect because, while both series add the same amount to the numerator, Series A adds twice as many shares, producing a materially different dilutive effect.', 'medium', 3)
;

COMMIT;
